package com.gukhan.ainlp.auth;
import com.gukhan.ainlp.security.JwtService;import com.gukhan.ainlp.user.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.NotBlank;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
@PostMapping("/login") public ResponseEntity<LoginResponse> login(@Valid @RequestBody LoginRequest r){var u=users.findByUsername(r.username()).filter(x->x.isActive()&&encoder.matches(r.password(),x.getPasswordHash())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));return ResponseEntity.ok(new LoginResponse(jwt.generate(u.getUsername(),u.getRole()),u.getUsername(),u.getRole()));}}
record LoginRequest(@NotBlank String username,@NotBlank String password){} record LoginResponse(String accessToken,String username,String role){}